30: interface NumberFieldProps {
31:   label: string;
32:   value: number;
33:   min: number;
34:   max: number;
35:   integer?: boolean;
36:   step?: number;
37:   suffix?: string;
38:   onChange(next: number): void;
39: }
40: 
41: function NumberField(props: NumberFieldProps): ReactElement {
42:   const error = describeValueError(props.value, props.min, props.max, props.integer);
43:   return (
44:     <label className={`inspector-field${error ? ' has-error' : ''}`}>
45:       <span className="inspector-field-label">{props.label}{props.suffix ? ` (${props.suffix})` : ''}</span>
46:       <input
47:         className="inspector-field-input"
48:         type="number"
49:         inputMode={props.integer ? 'numeric' : 'decimal'}
50:         step={props.step ?? (props.integer ? 1 : 0.5)}
51:         min={props.min}
52:         max={props.max}
53:         value={Number.isFinite(props.value) ? props.value : ''}
54:         aria-invalid={error ? 'true' : 'false'}
55:         onChange={(event) => {
56:           const raw = event.target.value;
57:           if (raw === '') {
58:             props.onChange(0);
59:             return;
60:           }
61:           const numeric = Number(raw);
62:           if (Number.isFinite(numeric)) {
63:             props.onChange(numeric);
64:           }
65:         }}
66:       />
67:       {error ? <span className="inspector-field-error">{error}</span> : null}
68:     </label>
69:   );
70: }
