72: function describeValueError(value: number, min: number, max: number, integer: boolean | undefined): string | null {
73:   if (!Number.isFinite(value)) return 'Value must be a finite number';
74:   if (value <= 0) return 'Value must be greater than zero';
75:   if (integer && !Number.isInteger(value)) return 'Value must be an integer';
76:   if (value < min) return `Value must be ≥ ${min}`;
77:   if (value > max) return `Value must be ≤ ${max}`;
78:   return null;
79: }
80: 
81: export function Inspector(): ReactElement {
82:   const primitive = useUiState((s) => s.primitive);
83:   const parameters = useUiState((s) => s.parameters);
84:   const preview = useUiState((s) => s.preview);
85: 
86:   const validation = validationFor(primitive, parameters);
87:   const source = preview.server ? 'server' : preview.local ? 'local' : 'none';
88:   const sourceLabel = source === 'server'
89:     ? 'Server verified'
90:     : source === 'local'
91:       ? 'Local preview'
92:       : 'No mesh yet';
93:   return (
94:     <section className="inspector" aria-label="Inspector">
95:       <header className="inspector-header">
96:         <h2>Inspector</h2>
97:         <span className="inspector-source" data-source={source}>
98:           {sourceLabel}
99:         </span>
100:       </header>
101:       <ParameterForm primitive={primitive} parameters={parameters} />
102:       {validation ? (
103:         <p className="inspector-validation" role="alert">
104:           {validation.message}
105:         </p>
106:       ) : null}
107:       {preview.local ? (
108:         <BoundsReadout
109:           parameters={parameters}
110:           bounds={preview.local.bounds}
111:           serverBounds={preview.server ? preview.server.preview.bounds : null}
112:         />
113:       ) : null}
114:     </section>
115:   );
116: }
117: 
118: function validationFor(kind: PrimitiveKind, p: StudioParameters) {
119:   if (kind === 'box') return validateBox(p as BoxParameters);
120:   if (kind === 'cylinder') return validateCylinder(p as CylinderParameters);
121:   return validateSphere(p as SphereParameters);
122: }
