184: // --- Box -----------------------------------------------------------------
185: //
186: // Six flat-shaded faces. Each face is a regular subdivision grid that
187: // emits CCW triangles when viewed from outside (so the face normal
188: // agrees with the geometric triangle normal). The triangle winding
189: // `(i0, i1, i2)` and `(i1, i3, i2)` produces a geometric normal of
190: // `+u × +v`; we choose `u` and `v` so that direction matches the face
191: // outward direction.
192: 
193: export function buildBox(p: BoxParameters): StudioLocalPreview {
194:   const err = validateBox(p);
195:   if (err) return emptyPreview('box', p);
196:   const hx = p.size_x / 2;
197:   const hy = p.size_y / 2;
198:   const hz = p.size_z / 2;
199:   const n = p.subdivisions;
200: 
201:   type Face = { normal: readonly [number, number, number]; uAxis: 0 | 1 | 2; vAxis: 0 | 1 | 2; constant: 0 | 1 | 2; offset: number };
202:   // For each axis sign we pick `u`, `v` so that `+u × +v` equals the
203:   // outward direction. The axis order is a right-handed cycle, so we
204:   // pair each constant axis with the next two in (X, Y, Z) order, with
205:   // the order swapped when the outward sign is negative.
206:   const faces: readonly Face[] = [
207:     { normal: [1, 0, 0], uAxis: 1, vAxis: 2, constant: 0, offset: hx },
208:     { normal: [-1, 0, 0], uAxis: 2, vAxis: 1, constant: 0, offset: -hx },
209:     { normal: [0, 1, 0], uAxis: 2, vAxis: 0, constant: 1, offset: hy },
210:     { normal: [0, -1, 0], uAxis: 0, vAxis: 2, constant: 1, offset: -hy },
211:     { normal: [0, 0, 1], uAxis: 0, vAxis: 1, constant: 2, offset: hz },
212:     { normal: [0, 0, -1], uAxis: 1, vAxis: 0, constant: 2, offset: -hz },
213:   ];
214: 
215:   const halfExtents: readonly [number, number, number] = [hx, hy, hz];
216:   const positions: number[] = [];
217:   const normals: number[] = [];
218:   const indices: number[] = [];
219:   for (const face of faces) {
220:     const base = positions.length / 3;
221:     for (let row = 0; row <= n; row++) {
222:       const v = (row / n) * 2 - 1;
223:       for (let col = 0; col <= n; col++) {
224:         const u = (col / n) * 2 - 1;
225:         const coord: [number, number, number] = [0, 0, 0];
226:         coord[face.uAxis] = u * halfExtents[face.uAxis]!;
227:         coord[face.vAxis] = v * halfExtents[face.vAxis]!;
228:         coord[face.constant] = face.offset;
229:         positions.push(coord[0], coord[1], coord[2]);
230:         normals.push(face.normal[0], face.normal[1], face.normal[2]);
231:       }
232:     }
233:     for (let row = 0; row < n; row++) {
234:       for (let col = 0; col < n; col++) {
235:         const i0 = base + row * (n + 1) + col;
236:         const i1 = i0 + 1;
237:         const i2 = i0 + (n + 1);
238:         const i3 = i2 + 1;
239:         // Geometric normal of `(i0, i1, i2)` is `+u × +v`, which by the
240:         // face table equals the outward direction.
241:         indices.push(i0, i1, i2);
242:         indices.push(i1, i3, i2);
243:       }
244:     }
245:   }
246:   return finishPreview('box', p, positions, normals, indices);
