249: // --- Cylinder ------------------------------------------------------------
250: //
251: // Side wall tessellated into radial_segments × height_segments quads with
252: // shared vertices giving smooth per-vertex normals; two end caps with their
253: // own pole-aligned normals. CCW when viewed from outside everywhere.
254: 
255: export function buildCylinder(p: CylinderParameters): StudioLocalPreview {
256:   const err = validateCylinder(p);
257:   if (err) return emptyPreview('cylinder', p);
258:   const radial = p.radial_segments;
259:   const rings = p.height_segments + 1;
260:   const halfH = p.height / 2;
261: 
262:   const positions: number[] = [];
263:   const normals: number[] = [];
264:   const indices: number[] = [];
265: 
266:   for (let ringIdx = 0; ringIdx < rings; ringIdx++) {
267:     const z = -halfH + (ringIdx / p.height_segments) * p.height;
268:     for (let seg = 0; seg <= radial; seg++) {
269:       const theta = (seg / radial) * TWO_PI;
270:       const cosT = Math.cos(theta);
271:       const sinT = Math.sin(theta);
272:       positions.push(p.radius * cosT, p.radius * sinT, z);
273:       normals.push(cosT, sinT, 0);
274:     }
275:   }
276:   for (let ringIdx = 0; ringIdx < p.height_segments; ringIdx++) {
277:     for (let seg = 0; seg < radial; seg++) {
278:       const i0 = ringIdx * (radial + 1) + seg;
279:       const i1 = i0 + 1;
280:       const i2 = i0 + (radial + 1);
281:       const i3 = i2 + 1;
282:       // CCW from outside the wall. Vertex grid is col-major over
283:       // (theta, z). With theta increasing first and z increasing second,
284:       // the geometric normal of (i0, i1, i2) is +theta × +z which points
285:       // radially outward at every quad.
286:       indices.push(i0, i1, i2);
287:       indices.push(i1, i3, i2);
288:     }
289:   }
290:   // Top cap: pole at +halfH.
291:   const topPole = positions.length / 3;
292:   positions.push(0, 0, halfH);
293:   normals.push(0, 0, 1);
294:   const topRingStart = positions.length / 3;
295:   for (let seg = 0; seg <= radial; seg++) {
296:     const theta = (seg / radial) * TWO_PI;
297:     const cosT = Math.cos(theta);
298:     const sinT = Math.sin(theta);
299:     positions.push(p.radius * cosT, p.radius * sinT, halfH);
300:     normals.push(0, 0, 1);
301:   }
302:   for (let seg = 0; seg < radial; seg++) {
303:     const i0 = topRingStart + seg;
304:     const i1 = i0 + 1;
305:     // CCW from above (+Z looking down at the cap): pole, then i0, then i1.
306:     indices.push(topPole, i0, i1);
307:   }
308:   // Bottom cap: pole at -halfH, winding reversed.
309:   const bottomPole = positions.length / 3;
310:   positions.push(0, 0, -halfH);
311:   normals.push(0, 0, -1);
312:   const bottomRingStart = positions.length / 3;
313:   for (let seg = 0; seg <= radial; seg++) {
314:     const theta = (seg / radial) * TWO_PI;
315:     const cosT = Math.cos(theta);
316:     const sinT = Math.sin(theta);
317:     positions.push(p.radius * cosT, p.radius * sinT, -halfH);
318:     normals.push(0, 0, -1);
319:   }
320:   for (let seg = 0; seg < radial; seg++) {
321:     const i0 = bottomRingStart + seg;
322:     const i1 = i0 + 1;
323:     indices.push(bottomPole, i1, i0);
324:   }
325: 
326:   return finishPreview('cylinder', p, positions, normals, indices);
327: }
