452: // --- Nominal geometry estimates -----------------------------------------
453: //
454: // Closed-form analytical values for the *ideal* solid each primitive
455: // represents — the same numbers an OpenCascade (OCP) volume/area property
456: // query returns for an unwrapped box, cylinder, or sphere of these
457: // dimensions. They are exact for the ideal solid (no fillet, draft, or
458: // tessellation error), which makes them useful for:
459: //
460: //   * early sizing and mass/volume sanity checks,
461: //   * quoting a bounding envelope to whoever does the detailed modelling,
462: //   * a neutral STEP/STL handoff into an external CAD/CAE package.
463: //
464: // They are deliberately NOT a simulation: nothing here is a stress, strain,
465: // deflection, or tolerance result. Callers must not present them as FEA.
466: //
467: // Every value is a magnitude, so a negative (already invalid) dimension
468: // still yields a well-formed extent rather than a negative volume. Range
469: // validation stays where it belongs — `validateParameters`.
470: 
471: export interface GeometryEstimate {
472:   /** Bounding-envelope extents ΔX, ΔY, ΔZ in millimetres. */
473:   envelopeMm: [number, number, number];
474:   /** Product of the envelope extents (ΔX · ΔY · ΔZ) in mm³. */
475:   envelopeVolumeMm3: number;
476:   /** Exact nominal solid volume in mm³. */
477:   volumeMm3: number;
478:   /** The same volume in cm³. */
479:   volumeCm3: number;
480:   /** Exact nominal surface area in mm². */
481:   surfaceAreaMm2: number;
482:   /** The same area in cm². */
483:   surfaceAreaCm2: number;
484: }
485: 
486: /**
487:  * Closed-form nominal geometry for a primitive. Pure: no DOM, no store, no
488:  * network. Units are millimetres throughout; the cm³/cm² members are simple
489:  * /1000 and /100 conversions so downstream CAD/CAE tools get both.
490:  */
491: export function computeGeometryEstimate(
492:   kind: PrimitiveKind,
493:   parameters: StudioParameters,
494: ): GeometryEstimate {
495:   if (kind === 'box') {
496:     const p = parameters as BoxParameters;
497:     const x = Math.abs(p.size_x);
498:     const y = Math.abs(p.size_y);
499:     const z = Math.abs(p.size_z);
500:     // V = X · Y · Z   A = 2(XY + YZ + ZX)
501:     return finishEstimate(
502:       [x, y, z],
503:       x * y * z,
504:       2 * (x * y + y * z + z * x),
505:     );
506:   }
507:   if (kind === 'cylinder') {
508:     const p = parameters as CylinderParameters;
509:     const radius = Math.abs(p.radius);
510:     const height = Math.abs(p.height);
511:     const diameter = radius * 2;
512:     // V = π r² h   A = 2πr(r + h)   (the side wall plus both end caps)
513:     return finishEstimate(
514:       [diameter, diameter, height],
515:       Math.PI * radius * radius * height,
516:       2 * Math.PI * radius * (radius + height),
517:     );
518:   }
519:   const p = parameters as SphereParameters;
520:   const radius = Math.abs(p.radius);
521:   const diameter = radius * 2;
522:   // V = ⁴⁄₃ π r³   A = 4πr²
523:   return finishEstimate(
524:     [diameter, diameter, diameter],
525:     (4 / 3) * Math.PI * radius ** 3,
526:     4 * Math.PI * radius * radius,
527:   );
528: }
