531:   envelopeMm: [number, number, number],
532:   volumeMm3: number,
533:   surfaceAreaMm2: number,
534: ): GeometryEstimate {
535:   return {
536:     envelopeMm,
537:     envelopeVolumeMm3: envelopeMm[0] * envelopeMm[1] * envelopeMm[2],
538:     volumeMm3,
539:     volumeCm3: volumeMm3 / 1000,
540:     surfaceAreaMm2,
541:     surfaceAreaCm2: surfaceAreaMm2 / 100,
542:   };
543: }
